/* ============================= MAIN COMPONENT ============================= */
export default function AnnDishaDashboard() {
  const [activeSection, setActiveSection] = useState("dashboard");
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [logoutModalOpen, setLogoutModalOpen] = useState(false);

  const [centerName] = useState("Rampur Procurement Center");
  const [dailyCapacity] = useState(500);
  const [language, setLanguage] = useState("en");
  const [smsAlerts, setSmsAlerts] = useState(true);
  const [appAlerts, setAppAlerts] = useState(true);
  const [autoQueueUpdate, setAutoQueueUpdate] = useState(true);
  const [totalFarmersRegistered, setTotalFarmersRegistered] = useState(1250);

  const [tokens, setTokens] = useState(INITIAL_TOKENS);
  const [completedTokens, setCompletedTokens] = useState(INITIAL_COMPLETED);

  const [farmerSearchTerm, setFarmerSearchTerm] = useState("");

  const [toasts, setToasts] = useState([]);
  const toastSeq = useRef(0);

  function addToast(msg, Icon = CheckCircle2) {
    const id = ++toastSeq.current;
    setToasts((t) => [...t, { id, msg, Icon }]);
    setTimeout(() => setToasts((t) => t.filter((x) => x.id !== id)), 3200);
  }

  /* ---------- derived values ---------- */
  const bookedQuintals = tokens.reduce((s, t) => s + t.qty, 0);
  const remainingQuintals = Math.max(0, dailyCapacity - bookedQuintals);
  const waitingCount = tokens.filter((t) => t.status === "Waiting").length;

  function nextActionFor(t) {
    const map = {
      Waiting: { label: "Call Farmer", Icon: Phone, next: "Called" },
      Called: { label: "Mark Arrived", Icon: CheckCircle2, next: "Arrived" },
      Arrived: { label: "Start Weighing", Icon: Scale, next: "Weighing" },
      Weighing: { label: "Complete", Icon: Check, next: "Completed" },
    };
    return map[t.status];
  }

  /* ---------- actions ---------- */
  function goTo(section) {
    setActiveSection(section);
    setSidebarOpen(false);
    window.scrollTo({ top: 0, behavior: "smooth" });
  }

  function handleVerify(token) {
    setTokens((ts) => ts.map((t) => (t.token === token ? { ...t, verified: true } : t)));
    addToast("Farmer marked as verified", ShieldCheck);
  }

  function callNextFarmer() {
    const waiting = tokens.find((t) => t.status === "Waiting");
    if (!waiting) {
      addToast("No farmers waiting in the queue", AlertTriangle);
      return;
    }
    setTokens((ts) => ts.map((t) => (t.token === waiting.token ? { ...t, status: "Called" } : t)));
    addToast(`${waiting.farmer} (${waiting.token}) has been called`, Phone);
  }

  function progressToken(token) {
    const t = tokens.find((x) => x.token === token);
    if (!t) return;
    const act = nextActionFor(t);
    if (!act) return;
    if (act.next === "Completed") {
      setCompletedTokens((cs) => [
        { token: t.token, farmer: t.farmer, farmerId: t.farmerId, village: t.village, crop: t.crop, qty: t.qty, payment: "Pending" },
        ...cs,
      ]);
      setTokens((ts) => ts.filter((x) => x.token !== token));
      addToast(`Procurement completed for ${t.farmer} (${t.token})`, Check);
    } else {
      setTokens((ts) => ts.map((x) => (x.token === token ? { ...x, status: act.next } : x)));
      addToast(`${t.farmer} (${t.token}) is now ${act.next}`, act.Icon);
    }
  }

  function cancelToken(token) {
    const t = tokens.find((x) => x.token === token);
    if (!t) return;
    if (window.confirm(`Cancel token ${t.token} for ${t.farmer}? This will free up ${t.qty} Quintals of capacity.`)) {
      setTokens((ts) => ts.filter((x) => x.token !== token));
      addToast(`Token ${t.token} cancelled`, X);
    }
  }

  function sendNotification(type) {
    const msg =
      type === "sms" ? "SMS sent to farmers in today's queue"
      : type === "app" ? "App notification sent to farmers in today's queue"
      : "Next 3 farmers notified about their upcoming slot";
    addToast(msg, Bell);
  }

  function handleLanguageChange(e) {
    const val = e.target.value;
    setLanguage(val);
    addToast(val === "hi" ? "भाषा हिन्दी में बदल दी गई है" : "Language set to English", Check);
  }

  function t(key, vars) {
    const dict = TRANSLATIONS[language] || TRANSLATIONS.en;
    let str = dict[key] ?? TRANSLATIONS.en[key] ?? key;
    if (vars) {
      Object.keys(vars).forEach((k) => { str = str.replace(`{${k}}`, vars[k]); });
    }
    return str;
  }

  function toggleLanguage() {
    setLanguage((prev) => {
      const next = prev === "en" ? "hi" : "en";
      addToast(TRANSLATIONS[next]["toast.langChanged"], Check);
      return next;
    });
  }

  /* ---------- small shared pieces ---------- */
  function Badge({ status }) {
    const Icon = STATUS_ICON[status] || Clock;
    return (
      <span className={`badge ${STATUS_CLASS[status] || "b-waiting"}`}>
        <Icon size={12} /> {status}
      </span>
    );
  }

  function KpiCard({ Icon, label, value, unit, color, bg }) {
    return (
      <div className="card kpi" style={{ "--kc": color, "--kc-bg": bg }}>
        <div className="kpi-icon">
          <Icon size={20} />
        </div>
        <div className="label">{label}</div>
        <div className="value num">
          {value} {unit ? <span className="unit">{unit}</span> : null}
        </div>
      </div>
    );
  }

  /* ============================= SECTIONS ============================= */
  function Dashboard() {
    const upcoming = tokens.filter((t) => t.status !== "Completed" && t.status !== "Cancelled").slice(0, 5);
    const scheduleSlice = tokens.slice(0, 4);

    const pct = Math.min(100, Math.round((bookedQuintals / dailyCapacity) * 100));
    let statusClass = "ok", statusMsg = t("capacity.available", { n: remainingQuintals }), StatusIconC = CheckCircle2;
    if (remainingQuintals <= 0) { statusClass = "full"; statusMsg = t("capacity.full"); StatusIconC = AlertTriangle; }
    else if (remainingQuintals <= 60) { statusClass = "warn"; statusMsg = t("capacity.almostFull", { n: remainingQuintals }); StatusIconC = AlertTriangle; }

    return (
      <>
        <div className="section-head">
          <div>
            <h2>{t("dashboard.overview")}</h2>
            <div className="muted">{todayLabel()} · {centerName}</div>
          </div>
        </div>

        <div className="kpi-grid">
          <KpiCard Icon={Users} label={t("kpi.totalFarmers")} value={totalFarmersRegistered.toLocaleString("en-IN")} unit="" color="var(--green-600)" bg="var(--green-100)" />
          <KpiCard Icon={Ticket} label={t("kpi.todaysTokens")} value={tokens.length + completedTokens.length} unit="" color="var(--gold-700)" bg="var(--gold-100)" />
          <KpiCard Icon={List} label={t("kpi.farmersWaiting")} value={waitingCount} unit="" color="var(--red-600)" bg="var(--red-100)" />
        </div>

        <div className="card capacity-card">
          <div className="capacity-top">
            <div>
              <h3>{t("capacity.title")}</h3>
              <div className="sub">{t("capacity.subtitle")}</div>
            </div>
          </div>
          <div className="capacity-figs">
            <div className="capacity-fig"><div className="f-label">{t("capacity.daily")}</div><div className="f-value num">{dailyCapacity} Q</div></div>
            <div className="capacity-fig"><div className="f-label">{t("capacity.booked")}</div><div className="f-value num">{bookedQuintals} Q</div></div>
            <div className="capacity-fig rem"><div className="f-label">{t("capacity.remaining")}</div><div className="f-value num">{remainingQuintals} Q</div></div>
          </div>
          <div className="progress-track"><div className="progress-fill" style={{ width: `${pct}%` }} /></div>
          <div className={`capacity-status ${statusClass}`}><StatusIconC size={18} /><span>{statusMsg}</span></div>
        </div>

        <div className="grid-2">
          <div className="card side-card">
            <h3>{t("queue.next")}</h3>
            {upcoming.length === 0 && <div className="empty-hint">{t("queue.empty")}</div>}
            {upcoming.map((t) => (
              <div className="mini-row" key={t.token}>
                <div>
                  <div className="who">{t.farmer}</div>
                  <div className="meta">{t.token} · {t.village} · {t.qty} Q · {t.slot}</div>
                </div>
                <Badge status={t.status} />
              </div>
            ))}
          </div>

          <div className="card panel">
            <div className="panel-head">
              <h3>{t("schedule.upcoming")}</h3>
            </div>
            <div className="timeline">
              {scheduleSlice.map((t, i) => (
                <div className="tl-row" key={t.token}>
                  <div className="tl-time">{t.slot}</div>
                  <div className="tl-dot-col"><div className="tl-dot" />{i < scheduleSlice.length - 1 && <div className="tl-line" />}</div>
                  <div className="tl-body">
                    <div className="name">{t.token} — {t.farmer}</div>
                    <div className="meta">{t.village} · {t.crop} · {t.qty} Q</div>
                  </div>
                  <Badge status={t.status} />
                </div>
              ))}
            </div>
          </div>
        </div>
      </>
    );
  }

  function Farmers() {
    const all = [...tokens, ...completedTokens.map((c) => ({ ...c, slot: "—", status: "Completed" }))];
    const term = farmerSearchTerm.trim().toLowerCase();
    const filtered = all.filter(
      (f) => !term || f.farmer.toLowerCase().includes(term) || f.farmerId.toLowerCase().includes(term) ||
        f.token.toLowerCase().includes(term) || (f.mobile || "").toLowerCase().includes(term)
    );
    return (
      <>
        <div className="section-head">
          <div><h2>Farmer Management</h2><div className="muted">{totalFarmersRegistered.toLocaleString("en-IN")} farmers registered at this center</div></div>
        </div>
        <div className="card panel">
          <div className="search-row">
            <div className="search-box">
              <Search size={17} />
              <input placeholder="Search by name, mobile number, farmer ID or token" value={farmerSearchTerm} onChange={(e) => setFarmerSearchTerm(e.target.value)} />
            </div>
          </div>
          <div className="table-wrap">
            <table>
              <thead><tr><th>Farmer</th><th>Farmer ID</th><th>Village</th><th>Crop</th><th>Qty</th><th>Token</th><th>Slot</th><th>Verification</th><th>Status</th><th>Actions</th></tr></thead>
              <tbody>
                {filtered.length === 0 && <tr><td colSpan={10}><div className="empty-hint">No farmers match your search</div></td></tr>}
                {filtered.map((f) => (
                  <tr key={f.token}>
                    <td className="cell-strong">{f.farmer}<div className="cell-sub">{f.mobile || "—"}</div></td>
                    <td>{f.farmerId}</td>
                    <td>{f.village}</td>
                    <td>{f.crop}</td>
                    <td>{f.qty} Q</td>
                    <td>{f.token}</td>
                    <td>{f.slot}</td>
                    <td>{f.verified === false ? <span className="badge b-unverified"><AlertTriangle size={12} /> Pending</span> : <span className="badge b-verified"><Check size={12} /> Verified</span>}</td>
                    <td><Badge status={f.status} /></td>
                    <td>
                      <div className="btn-row">
                        <button className="btn btn-ghost btn-sm" onClick={() => addToast(`Viewing details for ${f.token}`, Eye)}><Eye size={14} /></button>
                        <button className="btn btn-ghost btn-sm" onClick={() => addToast(`Editing record for ${f.token}`, Edit3)}><Edit3 size={14} /></button>
                        {f.verified === false && <button className="btn btn-gold btn-sm" onClick={() => handleVerify(f.token)}><ShieldCheck size={14} /> Verify</button>}
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </>
    );
  }

  function Procurement() {
    const all = [
      ...tokens.map((t) => ({ ...t })),
      ...completedTokens.map((c) => ({ ...c, status: "Completed" })),
    ];
    return (
      <>
        <div className="section-head"><div><h2>Procurement Status</h2><div className="muted">Track every farmer through the procurement journey</div></div></div>
        <div className="grid-2" style={{ gridTemplateColumns: "1fr 1fr" }}>
          {all.map((t) => {
            const isCompleted = t.status === "Completed";
            return (
              <div className="card procure-card" key={t.token}>
                <div className="ph">
                  <div><div className="name">{t.farmer}</div><div className="meta">Token: {t.token} · Quantity: {t.qty} Quintals</div></div>
                  <Badge status={t.status} />
                </div>
                <div className="stepper">
                  <span className={`step-pill ${!isCompleted ? "current" : ""}`}>
                    {isCompleted ? <Check size={13} /> : <Clock size={13} />} Ongoing
                  </span>
                  <span className={`step-pill ${isCompleted ? "done" : ""}`}>
                    {isCompleted ? <Check size={13} /> : <Clock size={13} />} Completed
                  </span>
                </div>
              </div>
            );
          })}
        </div>
      </>
    );
  }

  function LiveQueue() {
    return (
      <>
        <div className="section-head">
          <div><h2>Live Queue</h2><div className="muted">{waitingCount} farmers waiting · updates automatically as tokens progress</div></div>
          <button className="btn btn-primary" onClick={callNextFarmer}><Phone size={17} /> Call Next Farmer</button>
        </div>
        <div className="card panel">
          <div className="table-wrap">
            <table>
              <thead><tr><th>Token</th><th>Farmer</th><th>Village</th><th>Crop</th><th>Quantity</th><th>Slot</th><th>Status</th><th>Action</th></tr></thead>
              <tbody>
                {tokens.length === 0 && <tr><td colSpan={8}><div className="empty-hint">Queue is empty for today</div></td></tr>}
                {tokens.map((t) => {
                  const act = nextActionFor(t);
                  return (
                    <tr key={t.token}>
                      <td className="cell-strong">{t.token}</td>
                      <td>{t.farmer}</td>
                      <td>{t.village}</td>
                      <td>{t.crop}</td>
                      <td>{t.qty} Q</td>
                      <td>{t.slot}</td>
                      <td><Badge status={t.status} /></td>
                      <td>
                        <div className="btn-row">
                          {act && <button className="btn btn-gold btn-sm" onClick={() => progressToken(t.token)}><act.Icon size={14} /> {act.label}</button>}
                          <button className="btn btn-danger-ghost btn-sm" onClick={() => cancelToken(t.token)}><X size={14} /></button>
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      </>
    );
  }

  function Notifications() {
    const upcoming = tokens.filter((t) => t.status === "Waiting");
    const called = tokens.filter((t) => t.status === "Called");
    return (
      <>
        <div className="section-head"><div><h2>Notification Center</h2><div className="muted">Keep farmers informed so they arrive at the right time</div></div></div>
        <div className="notif-grid">
          <div className="card panel">
            <div className="panel-head"><h3>Send a Notification</h3></div>
            <div className="btn-row">
              <button className="btn btn-primary" onClick={() => sendNotification("sms")}><Phone size={17} /> Send SMS</button>
              <button className="btn btn-gold" onClick={() => sendNotification("app")}><Bell size={17} /> Send App Notification</button>
              <button className="btn btn-ghost" onClick={() => sendNotification("next")}><MessageSquare size={17} /> Notify Next Farmers</button>
            </div>
            <div className="notif-preview">
              <div className="tag">Sample message</div>
              Your token A101 is scheduled for 10:00 AM. Please arrive at the procurement center at your assigned time.
            </div>
          </div>
          <div className="card panel">
            <h3 style={{ marginBottom: 14 }}>Queue Status</h3>
            <div className="list-simple">
              <div style={{ fontWeight: 800, fontSize: 13, color: "var(--ink-soft)", marginBottom: 4 }}>Upcoming Farmers ({upcoming.length})</div>
              {upcoming.length === 0 && <div className="cell-sub" style={{ padding: "6px 0 12px" }}>None waiting</div>}
              {upcoming.map((t) => <div className="li" key={t.token}><span>{t.farmer} · {t.token}</span><span className="cell-sub">{t.slot}</span></div>)}
              <div style={{ fontWeight: 800, fontSize: 13, color: "var(--ink-soft)", margin: "10px 0 4px" }}>Farmers Called ({called.length})</div>
              {called.length === 0 && <div className="cell-sub" style={{ padding: "6px 0 12px" }}>None called yet</div>}
              {called.map((t) => <div className="li" key={t.token}><span>{t.farmer} · {t.token}</span><span className="cell-sub">{t.slot}</span></div>)}
              <div style={{ fontWeight: 800, fontSize: 13, color: "var(--ink-soft)", margin: "10px 0 4px" }}>Not Yet Arrived ({called.length})</div>
              {called.length === 0 ? <div className="cell-sub" style={{ padding: "6px 0" }}>Everyone called has arrived</div> :
                called.map((t) => <div className="li" key={t.token + "b"}><span>{t.farmer} · {t.token}</span><span className="cell-sub">{t.slot}</span></div>)}
            </div>
          </div>
        </div>
      </>
    );
  }

  function Reports() {
    return (
      <>
        <div className="section-head"><div><h2>Reports</h2><div className="muted">Simple, exportable summaries — no complex charts</div></div></div>
        <div className="report-grid">
          {REPORTS.map((r) => (
            <div className="card report-card" key={r.name}>
              <div className="ricon"><r.Icon size={19} /></div>
              <h4>{r.name}</h4>
              <p>{r.desc}</p>
              <div className="btn-row">
                <button className="btn btn-ghost btn-sm" onClick={() => addToast(`Opening ${r.name} report`, Eye)}><Eye size={14} /> View</button>
                <button className="btn btn-ghost btn-sm" onClick={() => addToast(`Downloading ${r.name} report`, Download)}><Download size={14} /> Download</button>
              </div>
            </div>
          ))}
        </div>
      </>
    );
  }

  function SettingsSection() {
    return (
      <>
        <div className="section-head"><div><h2>Settings</h2><div className="muted">Platform preferences</div></div></div>
        <div className="settings-grid">
          <div className="card panel">
            <div className="panel-head"><h3>Preferences</h3></div>
            <div className="toggle-row"><span>SMS alerts to farmers</span><button className={`switch ${smsAlerts ? "on" : ""}`} onClick={() => setSmsAlerts((v) => !v)} /></div>
            <div className="toggle-row"><span>App notifications</span><button className={`switch ${appAlerts ? "on" : ""}`} onClick={() => setAppAlerts((v) => !v)} /></div>
            <div className="toggle-row"><span>Auto-update queue on call</span><button className={`switch ${autoQueueUpdate ? "on" : ""}`} onClick={() => setAutoQueueUpdate((v) => !v)} /></div>
            <div className="field" style={{ marginTop: 16 }}>
              <label>Interface Language / भाषा</label>
              <select value={language} onChange={handleLanguageChange}>
                <option value="en">English</option>
                <option value="hi">हिन्दी (Hindi)</option>
              </select>
            </div>
          </div>
        </div>
      </>
    );
  }

  const SECTION_MAP = {
    dashboard: Dashboard, farmers: Farmers,
    procurement: Procurement, queue: LiveQueue, notifications: Notifications,
    reports: Reports, settings: SettingsSection,
  };
  const ActiveSectionComponent = SECTION_MAP[activeSection];

  const greetingHour = new Date().getHours();
  const greeting = greetingHour < 12 ? t("greeting.morning") : greetingHour < 17 ? t("greeting.afternoon") : t("greeting.evening");

  /* ============================= RENDER ============================= */
  return (
    <div className="app-root">
      <div className="app">
        {sidebarOpen && <div className="sidebar-backdrop show" onClick={() => setSidebarOpen(false)} />}

        <aside className={`sidebar ${sidebarOpen ? "open" : ""}`}>
          <div className="sidebar-brand">
            <img src={LOGO_SRC} alt="AnnDisha logo" />
            <div>
              <div className="brand-name">AnnDisha</div>
              <div className="brand-tag">{t("brand.tagline")}</div>
            </div>
          </div>
          <nav className="sidebar-nav">
            {NAV_ITEMS.map((item) => (
              <button key={item.id} className={`nav-item ${activeSection === item.id ? "active" : ""}`} onClick={() => goTo(item.id)}>
                <item.Icon size={19} /><span>{t(`nav.${item.id}`)}</span>
              </button>
            ))}
            <div className="nav-divider" />
            <div className="nav-logout">
              <button className="nav-item" onClick={() => setLogoutModalOpen(true)}><LogOut size={19} /><span>{t("nav.logout")}</span></button>
            </div>
          </nav>
        </aside>

        <div className="main">
          <header className="topbar">
            <div className="topbar-left">
              <button className="hamburger" aria-label="Open menu" onClick={() => setSidebarOpen((v) => !v)}><Menu size={20} /></button>
              <div className="greeting-block">
                <h1>{greeting}</h1>
                <div className="greeting-sub">
                  <span><Truck size={14} /></span><span>{centerName}</span>
                  <span><Calendar size={14} /></span><span>{todayLabel()}</span>
                </div>
              </div>
            </div>
            <div className="topbar-right">
              <button
                className="icon-btn lang-toggle"
                title={t("topbar.language")}
                aria-label={t("topbar.language")}
                onClick={toggleLanguage}
              >
                <span className="lang-code">{language === "en" ? "EN" : "हिं"}</span>
              </button>
              <button className="icon-btn" title={t("topbar.notifications")} onClick={() => addToast("3 new alerts: capacity almost full, 1 payment failed, 2 new complaints", Bell)}>
                <span className="dot-badge" /><Bell size={19} />
              </button>
              <div className="admin-chip">
                <div className="admin-avatar">RA</div>
                <div><div className="who">Ramesh Arora</div><div className="role">{t("admin.role")}</div></div>
              </div>
            </div>
          </header>

          <main className="content">
            <ActiveSectionComponent />
          </main>
        </div>
      </div>

      <div className="toast-wrap">
        {toasts.map((t) => (
          <div className="toast" key={t.id}><t.Icon size={17} /><span>{t.msg}</span></div>
        ))}
      </div>

      <div className={`modal-overlay ${logoutModalOpen ? "show" : ""}`}>
        <div className="modal-box">
          <h3>{t("logout.title")}</h3>
          <p>{t("logout.body")}</p>
          <div className="modal-actions">
            <button className="btn btn-ghost" onClick={() => setLogoutModalOpen(false)}>{t("logout.cancel")}</button>
            <button className="btn btn-primary" onClick={() => { setLogoutModalOpen(false); addToast("You have been logged out (demo)", LogOut); }}>{t("logout.confirm")}</button>
          </div>
        </div>
      </div>
    </div>
  );
}

